CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), clerk_user_id text NOT NULL, name text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', role text NOT NULL CHECK (role IN ('OWNER','ADMIN','MANAGER','STAFF','VIEWER')), status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,clerk_user_id), UNIQUE(organization_id,id)); CREATE INDEX users_clerk_idx ON users(clerk_user_id);
